var n={en:`A new Loyalty service awards points after completed paid orders and reverses them on refunds. Messages may arrive more than once.`,ua:`Новий сервіс Loyalty нараховує бали за оплачені завершені замовлення й скасовує їх при поверненні. Повідомлення можуть дублюватися.`};var r={en:[`Add Loyalty as an owner of its own points ledger.`,`Model award and reversal event contracts.`,`Include deduplication, reordering and notification failures.`],ua:[`Додай Loyalty як власника журналу балів.`,`Змоделюй події нарахування та сторнування.`,`Передбач дедуплікацію, інший порядок подій і помилки сповіщень.`]};var t=[{en:`Loyalty never writes Orders or Payments private tables.`,ua:`Loyalty не пише у приватні таблиці Orders чи Payments.`},{en:`Each original transaction produces at most one effective point adjustment.`,ua:`Одна транзакція створює не більше одного ефективного коригування балів.`}];var o={scenario:n,tasks:r,checks:t};export{t as checks,o as default,n as scenario,r as tasks};